		const APP_MARKUP = "<div id=\"app\">\n  <div id=\"hud-top\">\n    <span class=\"brand\">◢ HRINFO // CORE</span>\n    <span class=\"sep\">│</span>\n    <span class=\"item\">MODE <b>OVERRIDE</b></span>\n    <span class=\"item\">JURISDICTION <b>CN-BJ-07</b></span>\n    <span class=\"item\">SESSION <b id=\"h-session\">————</b></span>\n    <span class=\"spacer\"></span>\n    <span class=\"item\">TIME <b id=\"h-time\">00:00:00</b></span>\n    <span class=\"sep\">│</span>\n    <span class=\"item live\">● REC</span>\n  </div>\n  <div id=\"workspace\">\n    <section class=\"w\" id=\"w-tele\">\n      <div class=\"w-head\"><span class=\"led\"></span>TELEMETRY / C-RAN</div>\n      <div class=\"w-body\" id=\"teleBody\">\n        <div class=\"sect\">Radio</div>\n        <div class=\"dt\"><span class=\"k\">BAND</span><span class=\"v\">n78 / n79</span></div>\n        <div class=\"dt\"><span class=\"k\">BW</span><span class=\"v\">100 MHz · SCS 30 kHz</span></div>\n        <div class=\"dt\"><span class=\"k\">MIMO</span><span class=\"v\">4×4 DL / 2×2 UL</span></div>\n        <div class=\"dt\"><span class=\"k\">PCI</span><span class=\"v\">207</span></div>\n        <div class=\"dt\"><span class=\"k\">TAC</span><span class=\"v\">4172</span></div>\n        <div class=\"dt\"><span class=\"k\">CELL</span><span class=\"v\">0x5A3F</span></div>\n        <div class=\"sect\">Protocol</div>\n        <div class=\"dt\"><span class=\"k\">RRC</span><span class=\"v ok\">CONNECTED</span></div>\n        <div class=\"dt\"><span class=\"k\">CIPHER</span><span class=\"v\">AES-256-GCM</span></div>\n        <div class=\"dt\"><span class=\"k\">INTEGRITY</span><span class=\"v\">NIA2 · CMAC</span></div>\n        <div class=\"dt\"><span class=\"k\">KEY ROT</span><span class=\"v\" id=\"h-krot\">200 ms</span></div>\n        <div class=\"sect\">Metrics</div>\n        <div class=\"dt\"><span class=\"k\">RSRP</span><span class=\"v\" id=\"h-rsrp\">-88 dBm</span></div>\n        <div class=\"dt\"><span class=\"k\">SINR</span><span class=\"v\" id=\"h-sinr\">22.4 dB</span></div>\n        <div class=\"dt\"><span class=\"k\">BLER</span><span class=\"v\" id=\"h-bler\">0.12 %</span></div>\n        <div class=\"dt\"><span class=\"k\">HARQ</span><span class=\"v\">16 proc</span></div>\n        <div class=\"sect\">Status</div>\n        <div class=\"dt\"><span class=\"k\">UPLINK</span><span class=\"v warn\" id=\"h-up\">SEVERED</span></div>\n        <div class=\"dt\"><span class=\"k\">ROOT CA</span><span class=\"v warn\" id=\"h-ca\">REPLACING</span></div>\n        <div class=\"dt\"><span class=\"k\">NODES</span><span class=\"v\" id=\"h-nodes\">47 / 47</span></div>\n      </div>\n    </section>\n    <section class=\"w\" id=\"w-main\">\n      <div class=\"w-head\"><span class=\"led red\"></span>HRINFO CORE TERMINAL</div>\n      <div class=\"w-body\" id=\"mainBody\"></div>\n    </section>\n    <section class=\"w\" id=\"w-code\">\n      <div class=\"w-head\"><span class=\"led\"></span>FIRMWARE INJECTION</div>\n      <div class=\"w-body\" id=\"codeBody\"></div>\n    </section>\n    <section class=\"w\" id=\"w-node\">\n      <div class=\"w-head\"><span class=\"led red\"></span>SWARM NODE MATRIX</div>\n      <div class=\"w-body\"><div id=\"nodeGrid\"></div></div>\n    </section>\n  </div>\n  <div id=\"hud-bot\">\n    <span class=\"item\">STAGE <b id=\"b-stage\">IDLE</b></span>\n    <span class=\"item\">NODE <b id=\"b-node\">00 / 47</b></span>\n    <span class=\"spacer\"></span>\n    <span class=\"item\">OVERRIDE</span>\n    <div class=\"prog\"><div class=\"fill\" id=\"b-fill\"></div></div>\n    <span class=\"pct\" id=\"b-pct\">0%</span>\n    <span class=\"spacer\"></span>\n    <span class=\"item\">NET <b id=\"b-net\">OFFLINE</b></span>\n    <span class=\"item\">CH <b>07</b></span>\n    <span class=\"item\">FPS <b id=\"b-fps\">60</b></span>\n  </div>\n</div><div id=\"dim\"></div><div id=\"final\">SYSTEM IS REWRITTEN</div>";
		//#endregion

		/**
		 * HRINFO falling-character rain.
		 *
		 * Rewritten using the techniques from glyph-rain (github.com/Toskan4134/glyph-rain,
		 * MIT), studied from its source rather than depended on: it is a dependency-free
		 * canvas effect, and the parts worth learning were the ones this module kept getting
		 * wrong. No code was copied; the six techniques below were reimplemented.
		 *
		 * What was adopted, and why:
		 *
		 *   1. THE CANVAS MUST BE TOLD TO FILL ITS BOX. A canvas is a replaced element: with
		 *      no CSS size it lays out at its attribute size, 300x150, however it is
		 *      positioned. Earlier versions here sized the backing store but only set
		 *      `position`/`inset`, so the element the browser composited was not the element
		 *      being measured — pixels were provably drawn and nothing appeared on screen.
		 *      `width:100%`/`height:100%` are now set explicitly.
		 *
		 *   2. ONE FULL REDRAW PER FRAME instead of surgical per-cell clearing. Clearing only
		 *      the cells that changed is cheaper, but any skipped or re-rolled cell leaves a
		 *      hole and the trail reads as dashes. The frame is cleared and repainted whole,
		 *      throttled to FPS.
		 *
		 *   3. A LANE HOLDS MANY DROPS, spaced by `gap`. One drop per column is what made the
		 *      rain fall in visible waves; a lane carrying as many drops as fit is what makes
		 *      it continuous.
		 *
		 *   4. TRAIL LENGTH AND SPEED IN SCREEN UNITS, not rows: `length` is a fraction of the
		 *      lane span and `speed` is cells per second, so the effect is identical at any
		 *      viewport size.
		 *
		 *   5. TRAILS ARE DRAWN AS A CONTIGUOUS RUN (`head - i`), never as "the cells that
		 *      changed since the previous frame".
		 *
		 *   6. THE CHARSET IS ONE ARRAY OVER THE WHOLE GRID with per-cell churn times, so a
		 *      glyph persists and mutates in place instead of being owned by a drop.
		 *
		 * The wordmark reveal is adopted too: the logo is rasterised to a mask and sampled per
		 * cell, and drops crossing a masked cell are drawn bright and steady while the rest of
		 * the rain stays dim. That is what makes the mark readable through the rain.
		 */
		
		/**
		 * Uppercase letters and digits.
		 *
		 * Katakana reads as Matrix pastiche but says nothing about this product, and every
		 * glyph here is guaranteed to exist in any monospace fallback, so nothing can render as
		 * a missing-glyph box. The mix is weighted toward letters so runs read as data rather
		 * than as numbers.
		 */
		const CHARSET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
		
		/** Grid cell in px; also the glyph size. */
		const CELL = 24
		/** Full-frame redraw rate. The frame is fully repainted, so this is the cost knob. */
		const FPS = 30
		/** Character changes per second, per cell. */
		const CHURN = 3
		/** Trail length as a fraction of the lane span. */
		const LENGTH = 0.2
		const LENGTH_RANDOM = 0.6
		/** Cells crossed per second, so speed does not change with the viewport. */
		const SPEED = 26
		const SPEED_RANDOM = 0.45
		/** Distance between consecutive drops of one lane, in lane spans. Lower = denser. */
		const GAP = 0.95
		const GAP_RANDOM = 0.6
		/** Trail colour steps, precomputed once. */
		const RAMP = 16
		/** Mask alpha at or below this is not part of the glyph. */
		const MASK_ALPHA = 60
		
		/**
		 * Opacity of the trail, head to tail.
		 *
		 * These are deliberately high. Measured at 0.9/0.55 the layer was composited but
		 * unreadable: 5.5% of the canvas carried ink, spread as thin strokes over ~27k cells
		 * at an average alpha of 0.34, which on a near-black ground reads as texture rather
		 * than as characters. "Painted" and "legible" are different bars and only the second
		 * one is the requirement.
		 */
		const HEAD_ALPHA = 1
		const TAIL_ALPHA = 0.34
		/** Cells whose glyph falls inside the wordmark mask. */
		const MARK_HEAD_ALPHA = 1
		const MARK_TAIL_ALPHA = 0.75
		
		const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v)
		const jitter = (v, r) => v * (1 + (Math.random() * 2 - 1) * r)
		
		/**
		 * Resolve any CSS colour to [r, g, b] by letting the browser parse it, rather than
		 * carrying a colour parser.
		 */
		const parseColor = (() => {
		  let ctx = null
		  return (value) => {
		    if (ctx === null) ctx = document.createElement('canvas').getContext('2d')
		    ctx.fillStyle = '#000000'
		    ctx.fillStyle = value
		    const s = ctx.fillStyle
		    if (s[0] === '#') return [1, 3, 5].map((i) => parseInt(s.slice(i, i + 2), 16))
		    return (s.match(/[\d.]+/g) || [0, 0, 0]).slice(0, 3).map(Number)
		  }
		})()
		
		/**
		 * Mount the rain layer inside `stage`.
		 * @param stage - element to attach the canvas to, and the source of the colour vars.
		 * @param options - `force` bypasses the reduced-motion check; `revealText` shapes the
		 *   rain into that word.
		 * @returns dispose function.
		 */
		function mountRain(stage, options = {}) {
		  const reduced =
		    typeof window.matchMedia === 'function' &&
		    window.matchMedia('(prefers-reduced-motion: reduce)').matches
		  if (options.force !== true && reduced) return () => {}
		
		  const readVar = (name, fallback) => {
		    const value = getComputedStyle(stage).getPropertyValue(name).trim()
		    return value === '' ? fallback : value
		  }
		  const from = parseColor(readVar('--rain', '#3f96e0'))
		  const to = parseColor(readVar('--rain-head', '#ffffff'))
		  const fontFamily = readVar('--rain-font', "ui-monospace, 'Courier New', Consolas, monospace")
		  const css = (c) => 'rgb(' + c.map((v) => clamp(Math.round(v), 0, 255)).join(',') + ')'
		  /** Head to tail: index 0 is the head. */
		  const ramp = Array.from({ length: RAMP }, (_, i) => {
		    const t = i / (RAMP - 1)
		    return css(to.map((v, k) => v + (from[k] - v) * t))
		  })
		  const hot = css(to)
		  /** Shadow colour for the glyph glow: the head colour at low alpha. */
		  const glow = 'rgba(' + to.map((v) => clamp(Math.round(v), 0, 255)).join(',') + ',0.55)'
		
		  const canvas = document.createElement('canvas')
		  canvas.className = 'hrinfo-rain'
		  canvas.setAttribute('aria-hidden', 'true')
		  Object.assign(canvas.style, {
		    position: 'absolute',
		    left: '0',
		    top: '0',
		    // Load-bearing: without an explicit CSS size a canvas lays out at 300x150 whatever
		    // its positioning, so the composited element is not the one being measured.
		    width: '100%',
		    height: '100%',
		    pointerEvents: 'none',
		    // 900 is the slot the ported sheet already reserves for the rain: above the dark
		    // backdrop (`.hrinfo-bg`, z-index 0), below the wordmark (`.hrinfo-stage`, 1000) and
		    // the passcode cells (`.hrinfo-lock`, 1200), all inside `.boot-stage`'s stacking
		    // context. The rain is a backdrop — anything above 1000 prints glyphs across the logo.
		    zIndex: '900',
		  })
		  // Mounted INSIDE the splash, as a child of `.boot-stage`.
		  //
		  // Two placements were tried before this one. Appending to `document.body` with
		  // `z-index:2147483300` outranks the whole overlay (`z-index:2147483000`), so the rain
		  // draws over the wordmark and the passcode panel — that is the reported defect.
		  // Appending it beside `#boot` (the splash root: `z-index:2000`, its own stacking
		  // context) hides it behind the splash instead. `.boot-stage` is the one ancestor that
		  // is full-viewport, carries no transform, and already orders
		  // `.hrinfo-bg` < `.hrinfo-stage` < `.hrinfo-lock`.
		  const rainHost = stage.querySelector('.boot-stage') ?? stage
		  rainHost.appendChild(canvas)
		
		  const ctx = canvas.getContext('2d')
		  if (ctx === null) return () => {}
		
		  // The reveal mask is rasterised offscreen with plain fillText rather than by loading
		  // the logo file, so there is no image decode, no CORS and no async step.
		  const layer = document.createElement('canvas')
		  const lctx = layer.getContext('2d')
		
		  let cols = 0
		  let rows = 0
		  let span = 0
		  let cell = CELL
		  let chars = []
		  let churnAt = null
		  let churnRate = null
		  let mask = null
		  let lanes = []
		  let raf = 0
		  let last = 0
		
		  const randChar = () => CHARSET[(Math.random() * CHARSET.length) | 0]
		  const font = () => Math.round(cell * 0.9) + 'px ' + fontFamily
		
		  const buildMask = () => {
		    mask = null
		    const w = canvas.width
		    const h = canvas.height
		    lctx.clearRect(0, 0, w, h)
		    const text = options.revealText
		    if (typeof text !== 'string' || text === '') return
		
		    const size = Math.round(Math.min(w / (text.length * 0.66), h * 0.42))
		    lctx.font = '600 ' + size + 'px ' + fontFamily
		    lctx.textAlign = 'center'
		    lctx.textBaseline = 'middle'
		    lctx.fillStyle = '#ffffff'
		    lctx.fillText(text, w / 2, h / 2)
		    const data = lctx.getImageData(0, 0, w, h).data
		    lctx.clearRect(0, 0, w, h)
		    lctx.textAlign = 'start'
		    lctx.textBaseline = 'top'
		
		    const next = new Uint8Array(cols * rows)
		    for (let r = 0; r < rows; r += 1) {
		      for (let c = 0; c < cols; c += 1) {
		        const x = Math.min(w - 1, c * cell + (cell >> 1))
		        const y = Math.min(h - 1, r * cell + (cell >> 1))
		        if (data[(y * w + x) * 4 + 3] > MASK_ALPHA) next[r * cols + c] = 1
		      }
		    }
		    mask = next
		  }
		
		  const newDrop = (at) => ({
		    units: clamp(jitter(LENGTH, LENGTH_RANDOM), 0.02, 1),
		    speed: Math.max(1, jitter(SPEED, SPEED_RANDOM)),
		    travel: at,
		  })
		
		  /**
		   * A lane holds as many drops as fit: the next leaves once the previous covered its
		   * gap. One drop per lane is what made earlier versions fall in waves.
		   */
		  const spawn = (lane, at) => {
		    lane.drops.push(newDrop(at))
		    lane.gap = clamp(jitter(GAP, GAP_RANDOM), 0.05, 5) * span
		  }
		
		  const resize = () => {
		    const w = Math.max(1, Math.round(canvas.clientWidth || stage.getBoundingClientRect().width))
		    const h = Math.max(1, Math.round(canvas.clientHeight || stage.getBoundingClientRect().height))
		    canvas.width = w
		    canvas.height = h
		    layer.width = w
		    layer.height = h
		
		    cell = CELL
		    cols = Math.ceil(w / cell)
		    rows = Math.ceil(h / cell)
		    span = rows
		
		    const n = cols * rows
		    chars = new Array(n)
		    churnAt = new Float64Array(n)
		    churnRate = new Float32Array(n)
		    const now = performance.now()
		    for (let i = 0; i < n; i += 1) {
		      chars[i] = randChar()
		      churnRate[i] = Math.max(0, jitter(CHURN, 0.5))
		      churnAt[i] = churnRate[i] === 0 ? Infinity : now + (Math.random() * 1000) / churnRate[i]
		    }
		
		    // Lanes keep their drops across a resize, so a resize does not restart the rain.
		    const old = lanes
		    lanes = Array.from({ length: cols }, (_, i) => old[i] || { i, drops: [], gap: 0 })
		    for (const lane of lanes) if (lane.drops.length === 0) spawn(lane, -Math.random() * span)
		
		    buildMask()
		  }
		
		  const draw = () => {
		    const w = canvas.width
		    const h = canvas.height
		    ctx.setTransform(1, 0, 0, 1, 0, 0)
		    ctx.clearRect(0, 0, w, h)
		    ctx.font = font()
		    ctx.textBaseline = 'top'
		    // A glow is what makes the strokes read at a glance instead of as fine texture.
		    ctx.shadowColor = glow
		    ctx.shadowBlur = Math.round(cell * 0.55)
		
		    for (const lane of lanes) {
		      for (const d of lane.drops) {
		        const len = Math.max(1, Math.round(d.units * span))
		        const head = Math.round(d.travel)
		        // The trail is a contiguous run behind the head. Drawing only "the cells that
		        // changed" leaves dashes; this cannot.
		        for (let i = 0; i < len; i += 1) {
		          const pos = head - i
		          if (pos < 0 || pos >= span) continue
		          const idx = pos * cols + lane.i
		          const onWordmark = mask !== null && mask[idx] === 1
		          const fade = 1 - i / len
		          ctx.globalAlpha = onWordmark
		            ? MARK_TAIL_ALPHA + fade * (MARK_HEAD_ALPHA - MARK_TAIL_ALPHA)
		            : TAIL_ALPHA + fade * (HEAD_ALPHA - TAIL_ALPHA)
		          ctx.fillStyle = onWordmark ? hot : ramp[Math.min(RAMP - 1, ((i / len) * RAMP * 2) | 0)]
		          ctx.fillText(chars[idx], lane.i * cell, pos * cell)
		        }
		      }
		    }
		    ctx.globalAlpha = 1
		    ctx.shadowBlur = 0
		  }
		
		  const frame = (time) => {
		    raf = window.requestAnimationFrame(frame)
		    const elapsed = time - last
		    if (elapsed < 1000 / FPS) return
		    const dt = Math.min(0.1, elapsed / 1000) || 0
		    last = time
		
		    // Churn: a glyph persists and mutates in place instead of belonging to a drop.
		    for (let i = 0; i < churnAt.length; i += 1) {
		      if (time < churnAt[i]) continue
		      churnAt[i] = time + 1000 / churnRate[i]
		      chars[i] = randChar()
		    }
		
		    for (const lane of lanes) {
		      const drops = lane.drops
		      const tail = drops[drops.length - 1]
		      if (tail === undefined) spawn(lane, -Math.random() * span)
		      else if (tail.travel >= lane.gap) spawn(lane, 0)
		
		      for (let k = drops.length - 1; k >= 0; k -= 1) {
		        const d = drops[k]
		        d.travel += d.speed * dt
		        if (Math.round(d.travel) - d.units * span > span) drops.splice(k, 1)
		      }
		    }
		
		    draw()
		  }
		
		  resize()
		  raf = window.requestAnimationFrame(frame)
		
		  const onResize = () => resize()
		  window.addEventListener('resize', onResize)
		
		  return () => {
		    if (raf !== 0) window.cancelAnimationFrame(raf)
		    raf = 0
		    window.removeEventListener('resize', onResize)
		    canvas.remove()
		    layer.width = 0
		    layer.height = 0
		  }
		}
		

		/**
		 * Password unlock layer for dsh-hrinfo-boot — browser half.
		 *
		 * Runs only when the host half reports that a password is configured. It freezes
		 * the splash on its final frame and shows a four-cell code panel under the
		 * wordmark; the main interface is only revealed once the host says yes.
		 *
		 * The candidate is POSTed to the host rather than compared here: a check in this
		 * file would ship the password to every visitor and be bypassable in one line.
		 *
		 * Dependency-free and cancellable, matching the rest of the plugin.
		 */
		
		/** Code length. Must match gate.mjs CODE_LENGTH. */
		const CODE_LENGTH = 4
		/** Accepted characters. Must match gate.mjs CODE_PATTERN. */
		const CODE_CHARS = /^[0-9A-Za-z]$/
		
		/**
		 * Build the unlock panel.
		 *
		 * @param options - `onSubmit(value)` performs the round trip and resolves to an
		 *   outcome object; the rest are display-only.
		 * @returns panel element, focus/dispose controls, and a way to report an outcome.
		 */
		function createLockPanel(options) {
		  const panel = document.createElement('form')
		  panel.className = 'hrinfo-lock'
		  panel.setAttribute('autocomplete', 'off')
		
		  const cells = document.createElement('div')
		  cells.className = 'hrinfo-lock-cells'
		
		  /** One cell per code position; the value lives here, not in a hidden input. */
		  const inputs = []
		  for (let i = 0; i < CODE_LENGTH; i += 1) {
		    const cell = document.createElement('div')
		    cell.className = 'hrinfo-lock-cell'
		    cell.dataset.index = String(i)
		    const input = document.createElement('input')
		    input.className = 'hrinfo-lock-input'
		    input.type = 'text'
		    input.inputMode = 'text'
		    input.maxLength = 1
		    input.autocomplete = 'off'
		    input.setAttribute('autocapitalize', 'off')
		    input.setAttribute('spellcheck', 'false')
		    input.setAttribute('aria-label', `Code digit ${i + 1}`)
		    const caret = document.createElement('span')
		    caret.className = 'hrinfo-lock-caret'
		    cell.append(input, caret)
		    cells.append(cell)
		    inputs.push({ cell, input })
		  }
		
		  const submit = document.createElement('button')
		  submit.className = 'hrinfo-lock-go'
		  submit.type = 'submit'
		  submit.textContent = options.submitLabel ?? 'UNLOCK'
		
		  const status = document.createElement('div')
		  status.className = 'hrinfo-lock-status'
		
		  const actions = document.createElement('div')
		  actions.className = 'hrinfo-lock-actions'
		  actions.append(submit)
		
		  panel.append(cells, actions, status)
		  if (typeof options.hint === 'string' && options.hint !== '') {
		    const hint = document.createElement('div')
		    hint.className = 'hrinfo-lock-hint'
		    hint.textContent = options.hint
		    panel.append(hint)
		  }
		
		  let busy = false
		  let disposed = false
		
		  const value = () => inputs.map((entry) => entry.input.value).join('')
		
		  const setActive = (index) => {
		    for (let i = 0; i < inputs.length; i += 1) {
		      inputs[i].cell.classList.toggle('is-active', i === index)
		      inputs[i].cell.classList.toggle('is-filled', inputs[i].input.value !== '')
		    }
		  }
		
		  const setStatus = (text, cls) => {
		    status.textContent = text
		    status.className = `hrinfo-lock-status${cls === undefined ? '' : ` ${cls}`}`
		  }
		
		  const focusAt = (index) => {
		    const target = Math.max(0, Math.min(inputs.length - 1, index))
		    inputs[target].input.focus()
		    inputs[target].input.select()
		    setActive(target)
		  }
		
		  /**
		   * Keep the caret in the panel without the user having to click.
		   *
		   * A single `focus()` on the next animation frame is not enough: at that moment the
		   * overlay may still be `pointer-events:none`, or the window itself may not yet be
		   * focused, and a rejected focus() call is silent — nothing retries it, so the user
		   * has to click the first cell. This focuses immediately, again on the next frame,
		   * again after the splash transition has settled, and again whenever the window
		   * regains focus.
		   */
		  const grabFocus = () => {
		    if (disposed) return
		    const empty = inputs.findIndex((entry) => entry.input.value === '')
		    focusAt(empty < 0 ? inputs.length - 1 : empty)
		  }
		
		  const focusTimers = []
		  const scheduleFocus = () => {
		    window.requestAnimationFrame(() => { if (!disposed) grabFocus() })
		    for (const delay of [60, 300, 900, 1600]) {
		      focusTimers.push(
		        window.setTimeout(() => { if (!disposed) grabFocus() }, delay),
		      )
		    }
		  }
		  const onWindowFocus = () => grabFocus()
		  window.addEventListener('focus', onWindowFocus)
		
		  const shake = () => {
		    panel.classList.remove('hrinfo-lock-shake')
		    // Force a reflow so removing and re-adding the class retriggers the animation.
		    void panel.offsetWidth
		    panel.classList.add('hrinfo-lock-shake')
		  }
		
		  /** Clear every cell and drop the caret back at the start. */
		  const clear = (focus = true) => {
		    for (const entry of inputs) entry.input.value = ''
		    setStatus('')
		    setActive(0)
		    if (focus) focusAt(0)
		    else for (const entry of inputs) entry.cell.classList.remove('is-filled')
		  }
		
		  const attempt = async () => {
		    const candidate = value()
		    if (candidate.length !== CODE_LENGTH) {
		      setStatus('ENTER 4 CHARACTERS', 'bad')
		      shake()
		      // Send the caret to the first gap rather than making the user hunt for it.
		      const gap = inputs.findIndex((entry) => entry.input.value === '')
		      focusAt(gap < 0 ? 0 : gap)
		      return
		    }
		    busy = true
		    submit.disabled = true
		    for (const entry of inputs) entry.input.disabled = true
		    setStatus('VERIFYING…', 'busy')
		
		    let outcome
		    try {
		      outcome = await options.onSubmit(candidate)
		    } catch (error) {
		      outcome = { ok: false, message: `ERROR: ${String(error && error.message)}` }
		    }
		
		    busy = false
		    submit.disabled = false
		    for (const entry of inputs) entry.input.disabled = false
		    if (disposed) return
		
		    if (outcome !== null && outcome.ok === true) {
		      setStatus('ACCESS GRANTED', 'ok')
		      panel.classList.add('hrinfo-lock-granted')
		      for (const entry of inputs) entry.input.blur()
		      return
		    }
		    clear()
		    setStatus(outcome?.message ?? 'DENIED', 'bad')
		    shake()
		  }
		
		  panel.addEventListener('submit', (event) => {
		    event.preventDefault()
		    if (!busy && !disposed) void attempt()
		  })
		
		  for (let i = 0; i < inputs.length; i += 1) {
		    const { input } = inputs[i]
		
		    input.addEventListener('input', () => {
		      // Keep only accepted characters: this field is a code, not free text.
		      const typed = input.value.replace(/[^0-9A-Za-z]/g, '')
		      input.value = typed.slice(-1)
		      setActive(i)
		      inputs[i].cell.classList.toggle('is-filled', input.value !== '')
		      if (input.value !== '' && i < inputs.length - 1) focusAt(i + 1)
		      setStatus('')
		      // Auto-submit once the code is complete: four cells have no ambiguity left.
		      if (value().length === CODE_LENGTH && !busy) window.setTimeout(() => { if (!busy && !disposed && value().length === CODE_LENGTH) void attempt() }, 120)
		    })
		
		    input.addEventListener('keydown', (event) => {
		      if (event.key === 'Backspace') {
		        if (input.value === '' && i > 0) {
		          event.preventDefault()
		          inputs[i - 1].input.value = ''
		          inputs[i - 1].cell.classList.remove('is-filled')
		          focusAt(i - 1)
		        } else {
		          input.value = ''
		          inputs[i].cell.classList.remove('is-filled')
		          setStatus('')
		        }
		        return
		      }
		      if (event.key === 'ArrowLeft') {
		        event.preventDefault()
		        focusAt(i - 1)
		        return
		      }
		      if (event.key === 'ArrowRight') {
		        event.preventDefault()
		        focusAt(i + 1)
		        return
		      }
		      if (event.key === 'Enter') {
		        event.preventDefault()
		        void attempt()
		      }
		    })
		
		    // Paste a whole code into any cell and spread it across the row.
		    input.addEventListener('paste', (event) => {
		      const text = (event.clipboardData?.getData('text') ?? '').replace(/[^0-9A-Za-z]/g, '')
		      if (text === '') return
		      event.preventDefault()
		      const chars = text.slice(0, CODE_LENGTH).split('')
		      for (let k = 0; k < chars.length; k += 1) {
		        inputs[k].input.value = chars[k]
		        inputs[k].cell.classList.toggle('is-filled', true)
		      }
		      focusAt(Math.min(chars.length, inputs.length - 1))
		      if (value().length === CODE_LENGTH && !busy) void attempt()
		    })
		
		    input.addEventListener('focus', () => setActive(i))
		  }
		
		  setActive(0)
		  scheduleFocus()
		
		  return {
		    element: panel,
		    focus: () => focusAt(0),
		    clear,
		    setStatus,
		    dispose: () => {
		      disposed = true
		      for (const id of focusTimers) window.clearTimeout(id)
		      focusTimers.length = 0
		      window.removeEventListener('focus', onWindowFocus)
		      panel.remove()
		    },
		  }
		}
		
		/** Stylesheet for the unlock panel, injected alongside it. */
